#ifndef ZOVUTILS_SHUF_BACKEND_H
#define ZOVUTILS_SHUF_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <stdint.h>
#include <unistd.h>
typedef struct{char**v;size_t n,cap;}zov_shufvec;
static inline int zov_shuf_add(zov_shufvec*x,const char*s,size_t n){if(x->n==x->cap){size_t c=x->cap?x->cap*2:32;char**p=(char**)realloc(x->v,c*sizeof(char*));if(!p)return 0;x->v=p;x->cap=c;}char*q=(char*)malloc(n+1);if(!q)return 0;memcpy(q,s,n);q[n]=0;x->v[x->n++]=q;return 1;}
static inline uint64_t zov_shuf_rand(uint64_t*x){*x^=*x>>12;*x^=*x<<25;*x^=*x>>27;return *x*2685821657736338717ULL;}
static inline int zov_shuf_num(const char*s,long long*out){char*e;errno=0;long long v=strtoll(s,&e,10);if(errno||e==s||*e)return 0;*out=v;return 1;}
static inline int zov_shuf_run(int argc,char**argv){int echo=0,repeat=0,zero=0;long long count=-1,lo=0,hi=-1;const char*file=NULL,*out_file=NULL;char**items=(char**)malloc((size_t)(argc+1)*sizeof(char*));if(!items)return 1;int ni=0;for(int i=0;i<argc;i++){const char*a=argv[i];if(!strcmp(a,"--help")){puts("Usage: shuf [OPTION]... [FILE]\n  or:  shuf -e [OPTION]... [ARG]...\n  or:  shuf -i LO-HI [OPTION]...\nWrite a random permutation of the input lines to standard output.\n  -e, --echo             treat each ARG as an input line\n  -i, --input-range=LO-HI  treat each number LO through HI as an input line\n  -n, --head-count=COUNT  output at most COUNT lines\n  -r, --repeat           output lines can be repeated\n  -z, --zero-terminated  line delimiter is NUL, not newline\n      --help             display this help and exit\n      --version          output version information and exit");free(items);return 0;}if(!strcmp(a,"--version")){puts("shuf (zovutils) 0.10.23");free(items);return 0;}if(!strcmp(a,"-e")||!strcmp(a,"--echo")){echo=1;continue;}if(!strcmp(a,"-o")||!strcmp(a,"--output")){if(i+1>=argc){fprintf(stderr,"shuf: option requires an argument -- 'o'\n");free(items);return 1;}out_file=argv[++i];continue;}if(!strncmp(a,"--output=",9)){out_file=a+9;continue;}if(!strcmp(a,"-r")||!strcmp(a,"--repeat")){repeat=1;continue;}if(!strcmp(a,"-z")||!strcmp(a,"--zero-terminated")){zero=1;continue;}if(!strcmp(a,"-n")||!strcmp(a,"--head-count")){if(i+1>=argc||!zov_shuf_num(argv[++i],&count)||count<0){fprintf(stderr,"shuf: invalid line count: '%s'\n",i<argc?argv[i]:"");free(items);return 1;}continue;}if(!strncmp(a,"--head-count=",13)){if(!zov_shuf_num(a+13,&count)||count<0){fprintf(stderr,"shuf: invalid line count: '%s'\n",a+13);free(items);return 1;}continue;}if(!strcmp(a,"-i")||!strcmp(a,"--input-range")){if(i+1>=argc){free(items);return 1;}a=argv[++i];goto range;}if(!strncmp(a,"--input-range=",14)){a+=14;range:{char*sep=strchr(a,'-');if(!sep){fprintf(stderr,"shuf: invalid input range: '%s'\n",a);free(items);return 1;}char*l=(char*)malloc((size_t)(sep-a)+1);memcpy(l,a,(size_t)(sep-a));l[sep-a]=0;if(!zov_shuf_num(l,&lo)||!zov_shuf_num(sep+1,&hi)||hi<lo){fprintf(stderr,"shuf: invalid input range: '%s'\n",a);free(l);free(items);return 1;}free(l);continue;}}if(a[0]=='-'&&strcmp(a,"-")){fprintf(stderr,"shuf: unrecognized option '%s'\nTry 'shuf --help' for more information.\n",a);free(items);return 1;}if(echo){items[ni++]=(char*)a;continue;}if(file){fprintf(stderr,"shuf: extra operand '%s'\nTry 'shuf --help' for more information.\n",a);free(items);return 1;}file=a;}zov_shufvec v={0};if(hi>=lo){uint64_t n=(uint64_t)(hi-lo)+1;if(n>1000000){free(items);return 1;}for(long long x=lo;x<=hi;x++){char b[64];snprintf(b,sizeof b,"%lld",x);if(!zov_shuf_add(&v,b,strlen(b))){free(items);return 1;}}}else if(echo){for(int i=0;i<ni;i++)if(!zov_shuf_add(&v,items[i],strlen(items[i])))return 1;}else{FILE*f=stdin;if(file&&strcmp(file,"-")){f=fopen(file,"rb");if(!f){fprintf(stderr,"shuf: %s: %s\n",file,strerror(errno));free(items);return 1;}}size_t cap=128,n=0;char*b=(char*)malloc(cap);if(!b){free(items);return 1;}int delim=zero?0:'\n',c;while((c=fgetc(f))!=EOF){if(c==delim){if(!zov_shuf_add(&v,b,n)){free(b);return 1;}n=0;}else{if(n+1>=cap){cap*=2;char*p=(char*)realloc(b,cap);if(!p){free(b);return 1;}b=p;}b[n++]=(char)c;}}if(n&&!zov_shuf_add(&v,b,n)){free(b);return 1;}free(b);if(f!=stdin)fclose(f);}FILE*out=stdout;if(out_file){out=fopen(out_file,"wb");if(!out){fprintf(stderr,"shuf: %s: %s\n",out_file,strerror(errno));free(items);for(size_t k=0;k<v.n;k++)free(v.v[k]);free(v.v);return 1;}}uint64_t seed=(uint64_t)time(NULL)^(uint64_t)getpid()<<32;if(!seed)seed=1;if(repeat){if(count<0)count=(long long)v.n;for(long long i=0;i<count&&v.n;i++){size_t j=(size_t)(zov_shuf_rand(&seed)%v.n);fwrite(v.v[j],1,strlen(v.v[j]),out);fputc(zero?0:'\n',out);}}else{for(size_t i=v.n;i>1;i--){size_t j=(size_t)(zov_shuf_rand(&seed)%i);char*t=v.v[i-1];v.v[i-1]=v.v[j];v.v[j]=t;}size_t n=count>=0&&(uint64_t)count<v.n?(size_t)count:v.n;for(size_t i=0;i<n;i++){fputs(v.v[i],out);fputc(zero?0:'\n',out);}}for(size_t i=0;i<v.n;i++)free(v.v[i]);free(v.v);free(items);if(out!=stdout&&fclose(out)!=0)return 1;return 0;}
#endif
